    @wraps(f)
    def decorated(*args, **kwargs):
        # 实现认证逻辑，例如从 session 中获取用户信息
        user = User()  # 假设从 session 中取出当前用户
        return f(user)
    return decorated

@app.route("/update_profile", methods=["POST"])
